BASE = r'F:\Projects\BoardGames\Корабль призрак'


def patch(p, pairs):
    s = open(p, encoding='utf-8').read()
    for a, b in pairs:
        if a not in s:
            raise SystemExit('НЕТ в %s: %s' % (os.path.basename(p), a[:100]))
        s = s.replace(a, b, 1)
    open(p, 'w', encoding='utf-8').write(s)


ISLAND_TXT = ('**Как это работает в приложении.** Когда корабль вошёл в следующую клетку и тип местности определён (значок на клетке или d6), Писарь **нажимает этот тип местности** в приложении. '
              'Приложение выбирает событие из **случайного пула** этого типа и называет страницу, на которую идти (Палуба, Борт или Порт).\n\n'
              '**Острова.** При входе на остров приложение решает не только «порт или событие», но и даёт острову **номер**: игроки записывают его на карте (например, ▲3). '
              'Остров может оказаться **портом** (разного типа) или **необитаемым островом**: тогда игроки идут на Палубу и выборами исследуют его. Торговать там нечем, но можно найти что-то или кого-то интересного. '
              'При **повторном заходе** на остров Писарь вводит в приложение его номер, и игроки попадают на **тот же** порт или остров, а не на случайный.\n\n'
              '**В прототипе** приложения нет: роль приложения играет Книга событий. Первый заход на остров: бросьте d6 по таблице островов (**1–2 порт**, затем d6 по таблице портов; **3–4 необитаемый остров** I1; **5–6 необитаемый остров** I2), '
              'присвойте острову следующий свободный **номер**, нарисуйте его на карте (▲1, ▲2…) и запишите в **Журнале островов** (Корабельный журнал): номер, клетка, что это. Повторный заход: найдите номер в журнале и читайте тот же порт или остров.\n\n')

